import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { ApiService } from '../../core/services/api.service';

@Component({
  selector: 'app-reviews',
  standalone: true,
  imports: [CommonModule, FormsModule],
  template: `
    <div class="page-header"><div class="container"><h2>Quản lý Đánh giá</h2></div></div>
    <section class="section">
      <div class="container">
        <div class="loading-spinner" *ngIf="loading"><div class="spinner"></div></div>
        <table class="data-table" *ngIf="!loading">
          <thead><tr><th>Người dùng</th><th>Nội dung</th><th>Rating</th><th>Ngày</th><th>Hành động</th></tr></thead>
          <tbody>
            <tr *ngFor="let r of reviews">
              <td>{{ r.user?.fullName }}</td>
              <td>{{ r.comment | slice:0:60 }}...</td>
              <td>{{ r.rating }}/5</td>
              <td>{{ r.createdAt | date:'dd/MM/yyyy' }}</td>
              <td><button class="btn btn-sm btn-danger" (click)="delete(r.id)">Xóa</button></td>
            </tr>
          </tbody>
        </table>
      </div>
    </section>
  `
})
export class ReviewsComponent implements OnInit {
  reviews: any[] = [];
  loading = true;
  constructor(private api: ApiService) {}
  ngOnInit() {
    // Load all destinations and their reviews
    this.api.getDestinations({ limit: 30 }).subscribe((res: any) => {
      const allReviews: any[] = [];
      res.data.forEach((d: any) => {
        if (d.reviews) allReviews.push(...d.reviews);
      });
      this.reviews = allReviews.sort((a: any, b: any) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());
      this.loading = false;
    }, () => { this.loading = false; });
  }
  delete(id: string) {
    if (confirm('Xác nhận xóa đánh giá?')) this.api.deleteReview(id).subscribe(() => this.ngOnInit());
  }
}
